// 확인용 — 키가 잘 들어갔는지 보기 (확인 뒤 지워도 돼요)
function testKey() {
  const key = PropertiesService.getScriptProperties().getProperty('GEMINI_API_KEY');
  Logger.log(key ? '키가 들어 있어요: ' + key.slice(0, 6) + '…' : '키가 없어요. 속성 이름을 확인하세요.');
}

// 기록이 쌓일 시트 탭 이름
const SHEET = 'PAPS처방';

// 쓸 모델 후보 — 앞에서부터 차례로 시도한다.
// 모델 이름은 자주 바뀌어서, 없는 모델(404)이면 다음 후보로 넘어가고
// 후보가 다 없으면 지금 쓸 수 있는 Flash 모델을 직접 찾아 쓴다.
const MODELS = ['gemini-3.8-flash', 'gemini-flash-latest', 'gemini-2.5-flash'];

// 웹앱 주소로 들어오면 index.html 화면을 보여 준다
function doGet() {
  return HtmlService.createHtmlOutputFromFile('index')
    .setTitle('PAPS 맞춤 운동 처방')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

// 화면에서 google.script.run.getPrescription(paps) 로 부른다
// paps 예: { grade: '중2', sex: '여', cardio: 4, strength: 3, flex: 2, power: 3, bmi: 2, like: '줄넘기' }
// 등급: 1등급(아주 좋음) ~ 5등급(노력 필요)
function getPrescription(paps) {
  // ① API 키는 코드에 쓰지 않고 스크립트 속성에서 꺼낸다
  const key = PropertiesService.getScriptProperties().getProperty('GEMINI_API_KEY');
  if (!key) return 'API 키가 없어요. 스크립트 속성에 GEMINI_API_KEY 를 넣어 주세요.';

  // ② AI에게 보낼 부탁(프롬프트) 만들기
  const prompt =
    '너는 학교 체육 선생님이야. 학생의 PAPS(학생건강체력평가) 결과를 보고 4주 운동 처방을 써 줘.\n' +
    '- 등급은 1등급이 가장 좋고 5등급이 노력이 필요한 단계야\n' +
    '- 등급이 낮은(숫자가 큰) 영역 1~2개를 골라 왜 중요한지 한 문장씩 설명해\n' +
    '- 학교나 집에서 도구 없이 할 수 있는 운동으로, 주 3회 하루 20분 루틴을 짜 줘 (운동 이름, 횟수나 시간)\n' +
    '- 좋아하는 운동이 있으면 루틴에 넣어 줘\n' +
    '- 1주차보다 4주차를 조금 늘리는 방법을 한 줄로 알려 줘\n' +
    '- 마지막에 안전 주의 한 줄과 응원 한 줄\n' +
    '- 중학생이 읽기 쉬운 한국어, 마크다운 기호(#, *)는 쓰지 마\n\n' +
    '학년: ' + paps.grade + ', 성별: ' + paps.sex + '\n' +
    '심폐지구력: ' + paps.cardio + '등급\n' +
    '근력·근지구력: ' + paps.strength + '등급\n' +
    '유연성: ' + paps.flex + '등급\n' +
    '순발력: ' + paps.power + '등급\n' +
    '체지방(BMI): ' + paps.bmi + '등급\n' +
    '좋아하는 운동: ' + (paps.like || '없음');

  // ③ Gemini 에게 보내고 처방 글 받기 (모델 고르기는 아래 askGemini 가 알아서)
  const plan = askGemini(key, prompt);

  // ④ 시트에 한 줄 남기기 (이름은 받지 않는다)
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET) || ss.insertSheet(SHEET);
  if (sheet.getLastRow() === 0) {
    sheet.appendRow(['시각', '학년', '성별', '심폐', '근력', '유연성', '순발력', '체지방', '좋아하는 운동', 'AI 처방']);
  }
  sheet.appendRow([new Date(), paps.grade, paps.sex, paps.cardio, paps.strength, paps.flex, paps.power, paps.bmi, paps.like, plan]);

  return plan;
}

// Gemini API 부르기 — 성공한 모델은 스크립트 속성 GEMINI_MODEL 에 기억해 두고 다음부터 먼저 쓴다
// 오류에 따라: 404(모델 없음)·429(이 모델 횟수 초과)·500/503(서버 바쁨) → 다음 모델로,
//              400/401/403(요청·키 문제) → 모델을 바꿔도 안 되니 바로 멈춘다
function askGemini(key, prompt) {
  const props = PropertiesService.getScriptProperties();
  const saved = props.getProperty('GEMINI_MODEL');
  const tried = [];
  let lastCode = 0;
  let models = saved ? [saved].concat(MODELS) : MODELS.slice();

  for (let round = 0; round < 2; round++) {
    for (const model of models) {
      if (tried.indexOf(model) >= 0) continue;
      tried.push(model);
      for (let attempt = 0; attempt < 2; attempt++) {
        const res = UrlFetchApp.fetch(
          'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent', {
            method: 'post',
            contentType: 'application/json',
            headers: { 'x-goog-api-key': key },
            payload: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
            muteHttpExceptions: true
          });
        const code = res.getResponseCode();
        if (code === 200) {
          if (model !== saved) props.setProperty('GEMINI_MODEL', model);
          return JSON.parse(res.getContentText()).candidates[0].content.parts[0].text;
        }
        lastCode = code;
        if (code === 400 || code === 401 || code === 403) return errorText(code);
        if ((code === 500 || code === 503) && attempt === 0) { Utilities.sleep(1500); continue; } // 서버가 바쁘면 잠깐 쉬고 한 번 더
        break;   // 다음 모델로
      }
    }
    // 후보가 다 안 되면: 내 키로 쓸 수 있는 모델 목록에서 Flash 모델을 찾는다 (한 번만)
    if (round === 0) models = findFlashModels(key);
  }
  return errorText(lastCode);
}

// 오류 번호를 학생이 알아듣는 말로
function errorText(code) {
  if (code === 503 || code === 500) return 'AI가 지금 너무 바빠요. 잠시 뒤 다시 눌러 주세요. (오류 ' + code + ')';
  if (code === 429) return '오늘 AI를 너무 많이 불렀어요. 잠시 뒤(또는 내일) 다시 해 주세요. (오류 429)';
  if (code === 401 || code === 403) return 'API 키가 맞지 않아요. 스크립트 속성의 GEMINI_API_KEY 를 확인해 주세요. (오류 ' + code + ')';
  if (code === 404) return '쓸 수 있는 Gemini 모델을 찾지 못했어요. AI Studio 에서 모델 이름을 확인해 주세요.';
  return '지금은 AI 처방을 받을 수 없어요. (오류 ' + code + ')';
}

// 지금 쓸 수 있는 모델 중 글을 만들 수 있는 Flash 모델 이름들 (최신 것부터)
function findFlashModels(key) {
  const res = UrlFetchApp.fetch('https://generativelanguage.googleapis.com/v1beta/models?pageSize=200', {
    headers: { 'x-goog-api-key': key },
    muteHttpExceptions: true
  });
  if (res.getResponseCode() !== 200) return [];
  return (JSON.parse(res.getContentText()).models || [])
    .filter(function (m) {
      return /flash/.test(m.name) && !/lite|image|tts|live|audio|embedding/.test(m.name) &&
        (m.supportedGenerationMethods || []).indexOf('generateContent') >= 0;
    })
    .map(function (m) { return m.name.replace('models/', ''); })
    .sort().reverse();
}
